{
  "version": "2.2.0",
  "name": "Walking skeleton of the Pirate Sea Race monorepo: the spec's layout, toolchain and one thin end-to-end path",
  "branch_prefix": "feature/skeleton",
  "prd": "docs/spec.md",
  "policy": "policy.json",
  "workers": [
    {
      "node_id": "game",
      "task": "game-task.md"
    }
  ],
  "reviewers": [
    {
      "reviewer_id": "general",
      "prompt": "builtin:general"
    },
    {
      "reviewer_id": "coverage",
      "prompt": "builtin:coverage"
    }
  ]
}

