import { describe, expect, it } from "vitest";
import { formatSummary } from "../reporters/testSummary.js";

/** The workflow verifier reads the last `# <key> N` line of each key and needs the parts to add up to `tests`. */
function parse(summary: string): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const match of summary.matchAll(/^[#ℹ]\s+(tests|pass|fail|skipped|cancelled|todo)\s+(\d+)\s*$/gm)) {
    counts[match[1]!] = Number(match[2]);
  }
  return counts;
}

describe("test summary reporter", () => {
  it("prints totals in the verifier's summary form", () => {
    expect(parse(formatSummary({ passed: 70, failed: 0, skipped: 0, cancelled: 0 }))).toEqual({
      tests: 70,
      pass: 70,
      fail: 0,
      skipped: 0,
      cancelled: 0,
    });
  });

  it("keeps the parts adding up to the total when tests fail, skip or never finish", () => {
    const counts = parse(formatSummary({ passed: 5, failed: 2, skipped: 1, cancelled: 3 }));
    expect(counts["tests"]).toBe(11);
    expect(counts["pass"]! + counts["fail"]! + counts["skipped"]! + counts["cancelled"]!).toBe(counts["tests"]);
  });
});

