import { startGameServer } from "@pirate-sea-race/server";
import { AHEAD, HeadlessClient, sleep } from "@pirate-sea-race/test-tools";
import { seaMap } from "@pirate-sea-race/content";
import { Buttons } from "@pirate-sea-race/protocol";
import { dockInReach, defaultSimulationConfig as config, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
const running = await startGameServer({ port: 0, testPlacement: true, handleSignals: false });
const endpoint = `http://127.0.0.1:${running.port}`;
const dock = seaMap.docks.find((d) => d.side === "S")!;
const berth = tileCentre(config, dock.tileX, dock.tileY);
const host = await HeadlessClient.create(endpoint);
await host.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY + 6, heading: 48 });
for (let round = 0; round < 12; round++) {
  host.sendInput({ ...AHEAD, buttons: Buttons.Interact }); await sleep(30);
  for (let beat = 0; beat < 9; beat++) { host.sendInput(AHEAD); await sleep(30); }
  const s = host.ship()!;
  console.log(`round ${round}: x ${s.x} y ${s.y} (berth ${berth.x},${berth.y}) speed ${s.speed} dock ${s.dock} heading ${s.heading} reach ${dockInReach(config, s.x, s.y)?.id} pathClear ${hullPathIsClear(config, s.x, s.y, berth.x, berth.y)}`);
  if (s.dock >= 0) break;
}
await host.leave(); await running.close(); process.exit(0);
EOF
