import { matchMaker } from "colyseus";
import { startGameServer } from "@pirate-sea-race/server";
import { AHEAD, HeadlessClient, sleep } from "@pirate-sea-race/test-tools";
import { seaMap } from "@pirate-sea-race/content";
import { Buttons } from "@pirate-sea-race/protocol";
const running = await startGameServer({ port: 0, testPlacement: true, handleSignals: false });
const endpoint = `http://127.0.0.1:${running.port}`;
const dock = seaMap.docks.find((d) => d.side === "S")!;
const host = await HeadlessClient.create(endpoint);
const room: any = matchMaker.getLocalRoomById(host.room.roomId);
await host.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY + 3, heading: 48 });
const log: string[] = [];
let lastTick = -1;
const timer = setInterval(() => {
  const sim = room.simulation; const gate = room.gates.get(host.sessionId);
  if (sim.worldTick !== lastTick) { lastTick = sim.worldTick; const s = sim.ships[0];
    const inp = gate.inputAt(sim.frame); log.push(`t${sim.worldTick} y${s.y - (dock.tileY*256+128)} v${s.speed} d${s.dock} in(${inp.moveY},${inp.buttons}) latch${gate.latchedButtons}`); }
}, 2);
for (let round = 0; round < 6; round++) {
  host.sendInput({ ...AHEAD, buttons: Buttons.Interact }); await sleep(30);
  for (let beat = 0; beat < 9; beat++) { host.sendInput(AHEAD); await sleep(30); }
}
clearInterval(timer);
console.log(log.slice(0, 60).join("\n"));
await host.leave(); await running.close(); process.exit(0);
EOF
